slots.SLOT02:
.front{background:var(--panel);border:2px solid var(--line);font-size:27px;box-shadow:0 2px 5px rgba(30,50,90,.08);}
.back{background:#fff7e6;border:2px solid var(--accent);transform:rotateY(180deg);font-size:27px;}
.back .ta{font-size:29px;color:var(--ink);}
.back .gl{font-size:14px;margin-top:8px;padding:2px 12px;border-radius:20px;color:#fff;}
.gl1{background:var(--g1);}.gl2{background:var(--g2);}.gl3{background:var(--g3);}

/* SORT drill */
.sortwrap{display:flex;flex-direction:column;align-items:center;justify-content:center;flex:1;gap:12px;}
.qcard{font-size:56px;font-weight:900;background:var(--panel);border:3px solid var(--line);border-radius:20px;

slots.SLOT12:
let rPool=[], rIdx=0, rState=0; // 0=ません表示, 1=なければ表示
const rcard=document.getElementById('rcard'), rsub=document.getElementById('rsub'), rcount=document.getElementById('rcount');
function rStart(){rPool=rshuffle(VERBS);rIdx=0;rState=0;rRender();}
function rRender(){
  const v=rPool[rIdx];
  if(rState===0){rcard.innerHTML='<span>'+v.m+' <span style="color:var(--accent);">→</span> ？</span>';rsub.textContent='（クリック）';}
  else{rcard.innerHTML='<span>'+v.m+'</span><div class="arrow">▼</div><span class="rta">'+v.ba+'</span>';rsub.innerHTML='<span class="gl gl'+v.g+'" style="padding:2px 12px;border-radius:20px;color:#fff;">'+GNAME[v.g]+'</span>　つぎへ →';}
